@startuml

class Factory {}

class Machine {
  + serialNumber : string
  + make : string
  + model : string
  + purchaseDate : date
}

class Worker {
  + name : string
  + birthDate : date
  + address : string
  + skills : string[]
}

class ProductType {
  + material : string
  + weight : float
}

class Product {
  + name : string
}

class Client {
  + name : string
  + address : string
  + phoneNumber : string
  + contactPerson : string
}

class PurchaseOrder {
  + orderNumber : string
  + dateMade : date
  + expectedDeliveryDate : date
  + actualDeliveryDate : date
}

class OrderLine {
  + quantity : int
}

Factory "1" -- "*" Machine : has
Machine "1..*" -- "1..*" Worker : is operated by
Machine "1" -- "1..*" ProductType : produces
ProductType "1" -- "*" Product : is type of
Client "1" -- "*" PurchaseOrder : issues
PurchaseOrder "1" *-- "1..*" OrderLine : contains
OrderLine "*" -- "1" Product : refers to

@enduml

